1: /*
2:  * Domain model for the personalized Home feed.
3:  *
4:  * The Home surface is made of two tabs:
5:  *
6:  *   - Community: a date grouped editorial feed served by the remote editorial
7:  *     service. It supports paging backwards one logical day at a time.
8:  *   - For You:   a personalized feed whose recommendation groups are derived by
9:  *     the application from the reader's saved interests, reading activity and
10:  *     saved articles. The result is cached per calendar date and feed language.
11:  *
12:  * Both tabs share the same presentation vocabulary (phase, empty reason and
13:  * recovery action) so that the empty / loading / content / error presentations
14:  * stay mutually coherent for every tab.
15:  */
16: 
17: /** The two tabs exposed by the Home surface. */
18: export enum HomeTab {
19:   COMMUNITY = 'COMMUNITY',
20:   FOR_YOU = 'FOR_YOU'
21: }
22: 
23: /**
24:  * The personalization choice captured by feed onboarding. The choice decides the
25:  * initial Home tab and is persisted, so later visits land on the same tab.
26:  */
27: export enum HomePreference {
28:   COMMUNITY = 'COMMUNITY',
29:   PERSONALIZED = 'PERSONALIZED'
30: }
31: 
32: /**
33:  * The recommendation groups produced for the For You tab. The order is the order
34:  * in which the groups are presented.
35:  */
36: export enum ForYouModuleType {
37:   BASED_ON_INTEREST = 'BASED_ON_INTEREST',
38:   BECAUSE_YOU_READ = 'BECAUSE_YOU_READ',
39:   CONTINUE_READING = 'CONTINUE_READING'
40: }
