54:   FEATURED_ARTICLE = 'FEATURED_ARTICLE',
55:   NEWS = 'NEWS',
56:   TOP_READ = 'TOP_READ',
57:   PIC_OF_THE_DAY = 'PIC_OF_THE_DAY',
58:   BASED_ON_INTEREST = 'BASED_ON_INTEREST',
59:   BECAUSE_YOU_READ = 'BECAUSE_YOU_READ',
60:   CONTINUE_READING = 'CONTINUE_READING',
61:   ARTICLE = 'ARTICLE'
