115: /**
116:  * Tag identifying which Home surface an effect belongs to. Effects always name
117:  * the surfaces they touch so that a single tab acting is observable.
118:  */
119: export enum FeedTabSurface {
120:   HOME = 'HOME',
121:   COMMUNITY = 'COMMUNITY',
122:   FOR_YOU = 'FOR_YOU',
123:   SETTINGS = 'SETTINGS',
