127: /* ------------------------------------------------------------------ *
128:  * Value helpers. Feed content arrives from remote leaves and from the
129:  * persisted snapshot as loosely typed values, so every read is funnelled
130:  * through a coercion that always yields a usable value.
131:  * ------------------------------------------------------------------ */
132: 
133: /** Reads a loosely typed value as text. */
134: export function textOf(value: Object | undefined): string {
135:   if (value === undefined || value === null) {
136:     return '';
137:   }
138:   const encoded: string = JSON.stringify(value);
139:   if (encoded.length > 1 && encoded.charAt(0) === '"' && encoded.charAt(encoded.length - 1) === '"') {
140:     return encoded.substring(1, encoded.length - 1);
141:   }
142:   return encoded;
143: }
144: 
145: /** Reads a loosely typed value as a number. */
146: export function numberOf(value: Object | undefined, fallback: number): number {
147:   if (value === undefined || value === null) {
148:     return fallback;
149:   }
150:   const encoded: string = JSON.stringify(value);
151:   const parsed: number = Number(encoded);
152:   return Number.isNaN(parsed) ? fallback : parsed;
153: }
154: 
155: /** Reads a loosely typed value as a boolean. */
156: export function booleanOf(value: Object | undefined, fallback: boolean): boolean {
157:   if (value === undefined || value === null) {
158:     return fallback;
159:   }
160:   const encoded: string = JSON.stringify(value);
161:   if (encoded === 'true') {
162:     return true;
163:   }
164:   if (encoded === 'false') {
165:     return false;
166:   }
167:   return fallback;
168: }
169: 
170: /** Reads a loosely typed value as an array. */
171: export function arrayOf(value: Object | undefined): Object[] {
172:   if (value === undefined || value === null) {
173:     return [];
174:   }
175:   const encoded: string = JSON.stringify(value);
176:   const parsed: Object | undefined = JSON.parse(encoded) as Object | undefined;
177:   if (parsed === undefined || parsed === null) {
178:     return [];
179:   }
180:   if (Array.isArray(parsed)) {
181:     return parsed as Object[];
182:   }
183:   return [parsed];
184: }
185: 
186: /** Reads a loosely typed value as a keyed record. Returns undefined for scalars and lists. */
187: export function recordOf(value: Object | undefined): Record<string, Object> | undefined {
188:   if (value === undefined || value === null) {
189:     return undefined;
190:   }
191:   const encoded: string = JSON.stringify(value);
192:   if (encoded.length === 0 || encoded.charAt(0) === '[' || encoded.charAt(0) === '"') {
193:     return undefined;
194:   }
195:   const parsed: Object | undefined = JSON.parse(encoded) as Object | undefined;
196:   if (parsed === undefined || parsed === null || Array.isArray(parsed)) {
197:     return undefined;
198:   }
199:   return parsed as Record<string, Object>;
200: }
201: 
202: /** Reads a loosely typed value as a list of strings. */
203: export function textListOf(value: Object | undefined): string[] {
204:   const raw: Object[] = arrayOf(value);
205:   const result: string[] = [];
206:   for (let index = 0; index < raw.length; index++) {
207:     const entry: string = textOf(raw[index]).trim();
208:     if (entry.length > 0) {
209:       result.push(entry);
210:     }
211:   }
212:   return result;
213: }
