215: /* ------------------------------------------------------------------ *
216:  * Enum coercion.
217:  * ------------------------------------------------------------------ */
218: 
219: export function homeTabOf(value: string): HomeTab | undefined {
220:   const normalized: string = value.trim().toUpperCase();
221:   if (normalized === HomeTab.COMMUNITY) {
222:     return HomeTab.COMMUNITY;
223:   }
224:   if (normalized === HomeTab.FOR_YOU) {
225:     return HomeTab.FOR_YOU;
226:   }
227:   return undefined;
228: }
229: 
230: export function homePreferenceOf(value: string): HomePreference {
231:   const normalized: string = value.trim().toUpperCase();
232:   return normalized === HomePreference.PERSONALIZED ? HomePreference.PERSONALIZED : HomePreference.COMMUNITY;
233: }
234: 
235: /** The initial Home tab implied by a persisted personalization choice. */
236: export function homeTabForPreference(preference: HomePreference): HomeTab {
237:   return preference === HomePreference.PERSONALIZED ? HomeTab.FOR_YOU : HomeTab.COMMUNITY;
238: }
239: 
240: export function feedPhaseOf(value: string): FeedPhase {
241:   const normalized: string = value.trim().toLowerCase();
242:   if (normalized === FeedPhase.LOADING) {
243:     return FeedPhase.LOADING;
244:   }
245:   if (normalized === FeedPhase.CONTENT) {
246:     return FeedPhase.CONTENT;
247:   }
248:   if (normalized === FeedPhase.CONTENT_WITH_INLINE_ERROR) {
249:     return FeedPhase.CONTENT_WITH_INLINE_ERROR;
250:   }
251:   if (normalized === FeedPhase.EMPTY) {
252:     return FeedPhase.EMPTY;
253:   }
254:   if (normalized === FeedPhase.ERROR) {
255:     return FeedPhase.ERROR;
256:   }
257:   return FeedPhase.IDLE;
258: }
259: 
260: export function feedCardTypeOf(value: string): FeedCardType {
261:   const normalized: string = value.trim().toUpperCase();
262:   if (normalized === FeedCardType.DAY_HEADER) {
263:     return FeedCardType.DAY_HEADER;
264:   }
265:   if (normalized === FeedCardType.FEATURED_ARTICLE) {
266:     return FeedCardType.FEATURED_ARTICLE;
267:   }
268:   if (normalized === FeedCardType.NEWS) {
269:     return FeedCardType.NEWS;
270:   }
271:   if (normalized === FeedCardType.TOP_READ) {
272:     return FeedCardType.TOP_READ;
273:   }
274:   if (normalized === FeedCardType.PIC_OF_THE_DAY) {
275:     return FeedCardType.PIC_OF_THE_DAY;
276:   }
277:   if (normalized === FeedCardType.BASED_ON_INTEREST) {
278:     return FeedCardType.BASED_ON_INTEREST;
279:   }
280:   if (normalized === FeedCardType.BECAUSE_YOU_READ) {
281:     return FeedCardType.BECAUSE_YOU_READ;
282:   }
283:   if (normalized === FeedCardType.CONTINUE_READING) {
284:     return FeedCardType.CONTINUE_READING;
285:   }
286:   return FeedCardType.ARTICLE;
287: }
288: 
289: export function isDayHeader(type: FeedCardType): boolean {
290:   return type === FeedCardType.DAY_HEADER;
291: }
292: 
293: /**
294:  * The module a card belongs to. Day headers group a Community day and therefore
295:  * do not belong to any editorial module.
296:  */
297: export function moduleTypeOfCard(type: FeedCardType): string {
298:   return isDayHeader(type) ? '' : `${type}`;
299: }
300: 
301: export function allForYouModuleTypes(): string[] {
302:   return [ForYouModuleType.BASED_ON_INTEREST, ForYouModuleType.BECAUSE_YOU_READ, ForYouModuleType.CONTINUE_READING];
303: }
304: 
305: export function allCommunityModuleTypes(): string[] {
306:   return [
307:     CommunityModuleType.FEATURED_ARTICLE, CommunityModuleType.NEWS,
308:     CommunityModuleType.TOP_READ, CommunityModuleType.PIC_OF_THE_DAY, CommunityModuleType.ARTICLE
309:   ];
310: }
311: 
312: export function isForYouModuleType(value: string): boolean {
313:   const known: string[] = allForYouModuleTypes();
314:   return known.indexOf(value) >= 0;
315: }
