317: /* ------------------------------------------------------------------ *
318:  * Feed content.
319:  * ------------------------------------------------------------------ */
320: 
321: /** A single renderable feed item. */
322: export class FeedCard {
323:   readonly type: FeedCardType;
324:   readonly identifier: string;
325:   readonly title: string;
326:   readonly logicalAge: number;
327:   readonly language: string;
328: 
329:   constructor(type: FeedCardType, identifier: string, title: string, logicalAge: number, language: string) {
330:     this.type = type;
331:     this.identifier = identifier;
332:     this.title = title.length > 0 ? title : identifier;
333:     this.logicalAge = logicalAge;
334:     this.language = language;
335:   }
336: 
337:   /** Stable identity used for de-duplication and for restoring a hidden card. */
338:   token(): string {
339:     return this.identifier.length > 0 ? `${this.type}:${this.identifier}` : `${this.type}`;
340:   }
341: 
342:   /** Identity compared against the persisted hidden card list. */
343:   hideKey(): string {
344:     return this.identifier.length > 0 ? this.identifier : `${this.type}`;
345:   }
346: 
347:   /** Identity that also encodes the logical day, used to restore an exact position. */
348:   positionKey(): string {
349:     return `${this.logicalAge}#${this.token()}`;
350:   }
351: }
352: 
353: /** Parses a `TYPE` or `TYPE:identifier` token into a card. */
354: export function feedCardFromToken(token: string, logicalAge: number, language: string): FeedCard {
355:   const trimmed: string = token.trim();
356:   const separator: number = trimmed.indexOf(':');
357:   if (separator < 0) {
358:     return new FeedCard(feedCardTypeOf(trimmed), '', trimmed, logicalAge, language);
359:   }
360:   const rawType: string = trimmed.substring(0, separator);
361:   const identifier: string = trimmed.substring(separator + 1);
362:   return new FeedCard(feedCardTypeOf(rawType), identifier, identifier, logicalAge, language);
363: }
364: 
365: /** Trims and drops empty card tokens. */
366: export function normalizeTokens(tokens: string[]): string[] {
367:   const result: string[] = [];
368:   for (let index = 0; index < tokens.length; index++) {
369:     const token: string = tokens[index].trim();
370:     if (token.length > 0) {
371:       result.push(token);
372:     }
373:   }
374:   return result;
375: }
376: 
377: /** Parses card tokens for one logical day, dropping anything unusable. */
378: export function parseTokensSafe(tokens: string[], logicalAge: number, language: string): FeedCard[] {
379:   const normalized: string[] = normalizeTokens(tokens);
380:   const cards: FeedCard[] = [];
381:   for (let index = 0; index < normalized.length; index++) {
382:     cards.push(feedCardFromToken(normalized[index], logicalAge, language));
383:   }
384:   return cards;
385: }
386: 
387: /** A recommendation group rendered by the For You tab. */
388: export class FeedModule {
389:   readonly type: string;
390:   readonly cards: FeedCard[];
391: 
392:   constructor(type: string, cards: FeedCard[]) {
393:     this.type = type;
394:     this.cards = cards;
395:   }
396: 
397:   visibleCards(hiddenCards: string[]): FeedCard[] {
398:     const result: FeedCard[] = [];
399:     for (let index = 0; index < this.cards.length; index++) {
400:       if (hiddenCards.indexOf(this.cards[index].hideKey()) < 0) {
401:         result.push(this.cards[index]);
402:       }
403:     }
404:     return result;
405:   }
406: 
407:   /** A module survives filtering while it still shows at least one card. */
408:   hasVisibleCard(hiddenCards: string[]): boolean {
409:     return this.visibleCards(hiddenCards).length > 0;
410:   }
411: }
412: 
413: /** Groups a flat card list into modules, preserving first appearance order. */
414: export function feedModulesFromCards(cards: FeedCard[]): FeedModule[] {
415:   const modules: FeedModule[] = [];
416:   for (let index = 0; index < cards.length; index++) {
417:     const card: FeedCard = cards[index];
418:     const type: string = moduleTypeOfCard(card.type);
419:     if (type.length === 0) {
420:       continue;
421:     }
422:     let target: FeedModule | undefined = undefined;
423:     for (let scan = 0; scan < modules.length; scan++) {
424:       if (modules[scan].type === type) {
425:         target = modules[scan];
426:         break;
427:       }
428:     }
429:     if (target === undefined) {
430:       modules.push(new FeedModule(type, [card]));
431:     } else {
432:       target.cards.push(card);
433:     }
434:   }
435:   return modules;
436: }
437: 
438: /* ------------------------------------------------------------------ *
439:  * Tab state.
440:  * ------------------------------------------------------------------ */
441: 
442: const PHASE_HISTORY_LIMIT = 16;
443: 
444: /** Mutable presentation state of the Community tab. */
445: export class CommunityFeedState {
446:   phase: FeedPhase = FeedPhase.IDLE;
447:   /** Cards exactly as received, before hidden card filtering. */
448:   backingCards: FeedCard[] = [];
449:   /** Cards after hidden card and hidden module filtering. */
450:   cards: FeedCard[] = [];
451:   language: string = '';
452:   date: string = '';
453:   /** The logical day the next request will ask for. Only advances on success. */
454:   nextLogicalAge: number = 0;
455:   /** The logical day of the request that failed, or -1. */
456:   failedLogicalAge: number = -1;
457:   retryAvailable: boolean = false;
458:   inlineError: boolean = false;
459:   loading: boolean = false;
460:   emptyReason: FeedEmptyReason = FeedEmptyReason.NONE;
461:   recoveryAction: FeedRecoveryAction = FeedRecoveryAction.NONE;
462:   /** Offered next to the primary recovery action, for example "go to Community". */
463:   secondaryRecoveryAction: FeedRecoveryAction = FeedRecoveryAction.NONE;
464:   lastSource: string = '';
465:   attempts: number = 0;
466:   phaseHistory: string[] = [];
467: 
468:   constructor() {
469:     this.phaseHistory.push(FeedPhase.IDLE);
470:   }
471: 
472:   hasContent(): boolean {
473:     return this.cards.length > 0;
474:   }
475: 
476:   newestLogicalAge(): number {
477:     let newest: number = -1;
478:     for (let index = 0; index < this.backingCards.length; index++) {
479:       if (isDayHeader(this.backingCards[index].type)) {
480:         continue;
481:       }
482:       if (this.backingCards[index].logicalAge > newest) {
483:         newest = this.backingCards[index].logicalAge;
484:       }
485:     }
486:     return newest;
487:   }
488: 
489:   pushHistory(phase: FeedPhase): void {
490:     const last: string = this.phaseHistory.length > 0 ? this.phaseHistory[this.phaseHistory.length - 1] : '';
491:     if (last !== phase) {
492:       this.phaseHistory.push(phase);
493:       if (this.phaseHistory.length > PHASE_HISTORY_LIMIT) {
494:         this.phaseHistory.shift();
495:       }
496:     }
497:   }
498: 
499:   /** Enters the loading presentation while keeping already available content. */
500:   beginLoading(source: FeedLoadSource): void {
501:     this.loading = true;
502:     this.lastSource = source;
503:     this.attempts++;
504:     this.pushHistory(FeedPhase.LOADING);
505:     if (!this.hasContent()) {
506:       this.phase = FeedPhase.LOADING;
507:       this.emptyReason = FeedEmptyReason.NONE;
508:       this.recoveryAction = FeedRecoveryAction.NONE;
509:       this.retryAvailable = false;
510:       this.inlineError = false;
511:     }
512:   }
513: 
514:   endLoading(): void {
515:     this.loading = false;
516:   }
517: 
518:   recordPhase(phase: FeedPhase): void {
519:     this.phase = phase;
520:     this.pushHistory(phase);
521:   }
522: 
523:   reset(language: string, date: string): void {
524:     this.backingCards = [];
525:     this.cards = [];
526:     this.language = language;
527:     this.date = date;
528:     this.phase = FeedPhase.IDLE;
529:     this.pushHistory(FeedPhase.IDLE);
530:     this.nextLogicalAge = 0;
531:     this.failedLogicalAge = -1;
532:     this.retryAvailable = false;
533:     this.inlineError = false;
534:     this.loading = false;
535:     this.emptyReason = FeedEmptyReason.NONE;
536:     this.recoveryAction = FeedRecoveryAction.NONE;
537:   }
538: 
539:   toRecord(): Record<string, Object> {
540:     const record: Record<string, Object> = {
541:       'phase': this.phase,
542:       'cards': cardTokens(this.cards),
543:       'language': this.language,
544:       'date': this.date,
545:       'cardCount': this.cards.length,
546:       'hasContent': this.hasContent(),
547:       'loading': this.loading,
548:       'retryAvailable': this.retryAvailable,
549:       'inlineError': this.inlineError,
550:       'emptyReason': this.emptyReason,
551:       'recoveryAction': this.recoveryAction,
552:       'secondaryRecoveryAction': this.secondaryRecoveryAction,
553:       'lastSource': this.lastSource,
554:       'attempts': this.attempts,
555:       'phaseHistory': this.phaseHistory,
556:       'hiddenModuleTypes': visibleModuleTypes(this.backingCards, [], [])
557:     };
558:     return record;
559:   }
560: }
