621:   }
622: 
623:   recordPhase(phase: FeedPhase): void {
624:     this.phase = phase;
625:     this.pushHistory(phase);
626:   }
627: 
628:   reset(language: string, date: string): void {
629:     this.backingModules = [];
630:     this.modules = [];
631:     this.language = language;
632:     this.date = date;
633:     this.phase = FeedPhase.IDLE;
634:     this.pushHistory(FeedPhase.IDLE);
635:     this.batchIndex = 0;
636:     this.failedBatch = -1;
637:     this.retryAvailable = false;
638:     this.inlineError = false;
639:     this.loading = false;
640:     this.stableResult = false;
641:     this.emptyReason = FeedEmptyReason.NONE;
