259:   script.forYouPages = pagesFrom(record, ['nextForYouFeed', 'forYouResponses', 'forYouPages', 'nextRecommendations']);
260:   script.communityFailures = failuresFrom(record, ['communityError', 'communityErrorType', 'nextCommunityError']);
261:   script.forYouFailures = failuresFrom(record, ['forYouError', 'forYouErrorType', 'nextForYouError']);
