265: function readAliased(record: Record<string, Object>, keys: string[]): Object | undefined {
266:   for (let index = 0; index < keys.length; index++) {
267:     const value: Object | undefined = record[keys[index]];
268:     if (value !== undefined && value !== null) {
269:       return value;
270:     }
271:   }
272:   return undefined;
273: }
274: 
275: function pagesFrom(record: Record<string, Object>, keys: string[]): ScriptedPage[] {
276:   const value: Object | undefined = readAliased(record, keys);
277:   if (value === undefined) {
278:     return [];
279:   }
280:   const pages: ScriptedPage[] = [];
281:   const encoded: string = JSON.stringify(value);
282:   const parsed: Object | undefined = JSON.parse(encoded) as Object | undefined;
283:   if (Array.isArray(parsed)) {
284:     const entries: Object[] = parsed as Object[];
285:     let multiPage: boolean = false;
286:     for (let index = 0; index < entries.length; index++) {
287:       const nested: Object | undefined = JSON.parse(JSON.stringify(entries[index])) as Object | undefined;
288:       if (nested !== undefined && Array.isArray(nested)) {
289:         multiPage = true;
290:         break;
291:       }
292:       const nestedRecord: Record<string, Object> | undefined = readRecord(nested);
293:       if (nestedRecord !== undefined && readAliased(nestedRecord, ['error', 'failure', 'exception']) !== undefined) {
294:         multiPage = true;
295:         break;
296:       }
297:     }
298:     if (!multiPage) {
299:       const tokens: string[] = normalizeTokens(tokensOf(entries));
300:       return [ScriptedPage.content(tokens)];
301:     }
302:     for (let index = 0; index < entries.length; index++) {
303:       const nested: Object | undefined = JSON.parse(JSON.stringify(entries[index])) as Object | undefined;
304:       if (nested === undefined) {
305:         continue;
306:       }
307:       if (Array.isArray(nested)) {
308:         pages.push(ScriptedPage.content(normalizeTokens(tokensOf(nested as Object[]))));
309:         continue;
310:       }
311:       const nestedRecord: Record<string, Object> | undefined = readRecord(nested);
312:       if (nestedRecord !== undefined) {
313:         const failure: Object | undefined = readAliased(nestedRecord, ['error', 'failure', 'exception']);
314:         if (failure !== undefined) {
315:           pages.push(ScriptedPage.failure(textOf(failure)));
316:           continue;
317:         }
318:       }
319:       pages.push(ScriptedPage.content(normalizeTokens(tokensOf([nested]))));
320:     }
321:     return pages;
322:   }
323:   const single: Record<string, Object> | undefined = readRecord(parsed);
324:   if (single !== undefined) {
325:     const failure: Object | undefined = readAliased(single, ['error', 'failure', 'exception']);
326:     if (failure !== undefined) {
327:       return [ScriptedPage.failure(textOf(failure))];
328:     }
329:   }
330:   return [ScriptedPage.content([])];
331: }
332: 
333: function readRecord(value: Object | undefined): Record<string, Object> | undefined {
334:   if (value === undefined || value === null) {
335:     return undefined;
336:   }
337:   const encoded: string = JSON.stringify(value);
338:   if (encoded.length === 0 || encoded.charAt(0) === '[' || encoded.charAt(0) === '"') {
339:     return undefined;
340:   }
341:   const parsed: Object | undefined = JSON.parse(encoded) as Object | undefined;
342:   if (parsed === undefined || parsed === null || Array.isArray(parsed)) {
343:     return undefined;
344:   }
345:   return parsed as Record<string, Object>;
346: }
347: 
348: function tokensOf(values: Object[]): string[] {
349:   const tokens: string[] = [];
350:   for (let index = 0; index < values.length; index++) {
351:     const record: Record<string, Object> | undefined = readRecord(values[index]);
352:     if (record !== undefined) {
353:       const type: string = textOf(record['type']).trim();
354:       const identifier: string = textOf(record['id']).trim().length > 0 ?
355:         textOf(record['id']).trim() : textOf(record['title']).trim();
356:       if (type.length > 0 || identifier.length > 0) {
357:         tokens.push(identifier.length > 0 ? `${type}:${identifier}` : type);
358:       }
359:       continue;
360:     }
361:     const token: string = textOf(values[index]).trim();
362:     if (token.length > 0) {
363:       tokens.push(token);
364:     }
365:   }
366:   return tokens;
367: }
368: 
369: function failuresFrom(record: Record<string, Object>, keys: string[]): string[] {
370:   const value: Object | undefined = readAliased(record, keys);
371:   if (value === undefined) {
372:     return [];
373:   }
374:   const encoded: string = JSON.stringify(value);
375:   const parsed: Object | undefined = JSON.parse(encoded) as Object | undefined;
376:   if (parsed !== undefined && Array.isArray(parsed)) {
377:     const entries: Object[] = parsed as Object[];
378:     const failures: string[] = [];
379:     for (let index = 0; index < entries.length; index++) {
380:       const entry: string = textOf(entries[index]).trim();
381:       if (entry.length > 0) {
382:         failures.push(entry);
383:       }
384:     }
385:     return failures;
386:   }
387:   if (parsed !== undefined && !Array.isArray(parsed)) {
388:     const single: Record<string, Object> | undefined = readRecord(parsed);
389:     if (single !== undefined) {
390:       const nested: Object | undefined = readAliased(single, ['error', 'failure', 'exception', 'name']);
391:       if (nested !== undefined) {
392:         const name: string = textOf(nested).trim();
393:         return name.length > 0 ? [name] : [];
394:       }
395:     }
396:   }
397:   const name: string = textOf(value).trim();
398:   return name.length > 0 ? [name] : [];
399: }

