199:   private constructor(store: preferences.Preferences, input: ExploreInput) {
200:     this.preferences = new FeedPreferences(store);
201:     this.leaf = input.leaf;
202:     this.snapshot = new FeedSnapshot(input.state, input.persistence);
203:     this.script = feedScriptFromSnapshot(this.snapshot.merged());
204:     this.clock = new FeedClock(this.snapshot.text(['clockDate', 'today', 'currentDate']));
205:     this.content = new FeedContentService(input.leaf, this.script);
206:     this.interestRepository = new FeedInterestRepository();
207:   }
