209:   /**
210:    * Installs the injected snapshot into durable storage and rebuilds the Home
211:    * state from it. The durable store is cleared first so a remount never mixes
212:    * two snapshots together.
213:    */
214:   static async create(context: common.UIAbilityContext, input: ExploreInput): Promise<LegacyExploreStore> {
215:     const store: preferences.Preferences = await preferences.getPreferences(context, 'explore_feed');
216:     await store.clear();
217:     await store.put(FeedStorageKeys.SNAPSHOT, JSON.stringify(input.persistence));
218:     await store.flush();
219:     const instance: LegacyExploreStore = new LegacyExploreStore(store, input);
220:     instance.context = context;
221:     await instance.initialize();
222:     LegacyExploreStore.runtime = instance;
223:     return instance;
224:   }
225: 
226:   /** The store backing the mounted Home surface. */
227:   static current(): LegacyExploreStore | undefined {
228:     return LegacyExploreStore.runtime;
229:   }
