231:   private async initialize(): Promise<void> {
232:     this.readConfiguration();
233:     this.hydrateTabs();
234:     await this.interestRepository.initialize(this.context as common.UIAbilityContext, this.interestsList);
235:     await this.reloadPersistence();
236:   }
