242:   private readConfiguration(): void {
243:     this.configuredLanguages = this.snapshot.list(['configuredLanguages', 'appLanguages']);
244:     this.primaryConfiguredLanguage = this.snapshot.text(['primaryConfiguredLanguage', 'primaryLanguage']);
245:     this.homeLanguage = this.snapshot.text(['homeLanguage', 'persistedHomeLanguage', 'feedLanguage', 'language']);
246:     this.homePreference = homePreferenceOf(this.snapshot.text(['homePreference', 'preference']));
247:     this.onboardingComplete = this.snapshot.flag(['onboardingComplete', 'onboarding'], true);
248:     this.interestsList = this.snapshot.list(['interests', 'persistedInterests', 'savedInterests']);
249:     this.savedArticles = this.snapshot.list(['savedArticles', 'savedPages']);
250:     this.readingActivity = this.snapshot.list(['readingHistory', 'recentlyRead', 'readHistory']);
251:     this.hiddenCards = this.snapshot.list(['hiddenCards', 'persistedHiddenCards']);
252:     this.hiddenCommunityModules = this.snapshot.list(
253:       ['hiddenCommunityModules', 'persistedCommunityHiddenModules', 'communityHiddenModules']);
254:     this.hiddenForYouModules = this.snapshot.list(
255:       ['hiddenModules', 'persistedHiddenModules', 'hiddenForYouModules', 'forYouHiddenModules']);
256:     const allOffTarget: string = this.snapshot.text(['pendingAllModulesOffTarget', 'allModulesOffTarget']);
257:     this.pendingAllModulesOffTarget = allOffTarget.length > 0 ?
258:       allOffTarget : `${FeedSettingsTarget.FOR_YOU_MODULES}`;
259:     this.pendingAllModulesOffConfirmation = this.snapshot.flag(
260:       ['pendingAllModulesOffConfirmation', 'allModulesOffPending'], true);
261:   }
262: 
263:   private hydrateTabs(): void {
264:     const community: Record<string, Object> | undefined = this.snapshot.record(['community', 'communityState']);
265:     const forYouRecord: Record<string, Object> | undefined = this.snapshot.record(['forYou', 'forYouState']);
266: 
267:     this.community.language = this.communityLanguage(community);
268:     this.community.date = this.clock.today();
269:     this.community.backingCards = parseCards(this.nested(community, ['cards']), 0, this.community.language);
270:     this.community.phase = feedPhaseFromText(this.snapshotText(community, ['phase'], ''));
271:     this.community.pushHistory(this.community.phase);
272: 
273:     const failedAge: number = this.snapshot.number(['failedLogicalAge'], -1);
274:     this.community.failedLogicalAge = failedAge;
275:     this.community.nextLogicalAge = failedAge >= 0 ? failedAge : this.community.newestLogicalAge() + 1;
276:     this.community.inlineError = this.community.phase === FeedPhase.CONTENT_WITH_INLINE_ERROR ||
277:       this.nestedFlag(community, ['inlineError'], false);
278:     this.community.retryAvailable = this.snapshot.flag(['retryAvailable'],
279:       this.community.phase === FeedPhase.ERROR || this.community.phase === FeedPhase.CONTENT_WITH_INLINE_ERROR);
280: 
281:     this.forYou.language = this.forYouLanguage(forYouRecord);
282:     this.forYou.date = normalizeDate(this.snapshotText(forYouRecord, ['date'], ''), this.clock.today());
283:     const forYouPhase: string = this.snapshotText(forYouRecord, ['phase'], '');
284:     this.forYou.phase = feedPhaseFromText(forYouPhase.length > 0 ?
285:       forYouPhase : this.snapshot.text(['forYouPhase']));
286:     this.forYou.pushHistory(this.forYou.phase);
287:     this.forYou.backingModules = this.hydratedForYouModules(forYouRecord);
288:     this.forYou.failedBatch = this.snapshot.number(['failedBatch'], -1);
289:     this.forYou.batchIndex = this.forYou.failedBatch >= 0 ? this.forYou.failedBatch : this.snapshot.number(
290:       ['forYouBatchIndex', 'batchIndex'], 0);
291:     this.forYou.retryAvailable = this.snapshot.flag(['retryAvailable'],
292:       this.forYou.phase === FeedPhase.ERROR || this.forYou.phase === FeedPhase.CONTENT_WITH_INLINE_ERROR);
293: 
294:     const tab: HomeTab | undefined = homeTabOf(this.snapshot.text(['selectedTab', 'tab']));
295:     this.selectedTab = tab === undefined ? homeTabForPreference(this.homePreference) : tab;
296: 
297:     this.restoreCacheFromSnapshot();
298: 
299:     this.editor.initialSelections = this.snapshot.list(['interestEditor', 'initialSelections']);
300:     this.editor.currentSelections = this.snapshot.list(['interestEditor', 'currentSelections']);
301:     this.editor.updated = this.snapshot.flag(['interestEditor', 'interestsUpdated'], false);
302:     this.editor.pendingResult = this.snapshot.number(['interestEditor', 'pendingResult'], -1);
303: 
304:     this.refreshCommunityPresentation();
305:     this.refreshForYouPresentation();
306:     this.consumeServedFailures();
307:     this.normalizePhases();
308:     this.evaluateCommunityEmptyState();
309:     this.evaluateForYouEmptyState();
310:   }
311: 
312:   /**
313:    * A failure the snapshot already shows as the current state of a tab has
314:    * already been served by the matching content leaf, so its scripted answer is
315:    * spent. Everything still queued belongs to the next request, which is what
316:    * lets a retry of the same logical day or batch reach the service again.
317:    */
318:   private consumeServedFailures(): void {
319:     if (this.community.retryAvailable && this.community.failedLogicalAge >= 0 &&
320:       this.script.communityFailures.length > 0) {
321:       this.script.communityFailures.shift();
322:     }
323:     if (this.forYou.retryAvailable && this.script.forYouFailures.length > 0) {
324:       this.script.forYouFailures.shift();
325:     }
326:   }
327: 
328:   /** Keeps each tab's phase consistent with what it actually shows. */
329:   private normalizePhases(): void {
330:     if (this.community.cards.length > 0) {
331:       if (this.community.phase === FeedPhase.IDLE || this.community.phase === FeedPhase.EMPTY) {
332:         this.community.recordPhase(this.community.inlineError ?
333:           FeedPhase.CONTENT_WITH_INLINE_ERROR : FeedPhase.CONTENT);
334:       }
335:     } else if (this.community.phase === FeedPhase.CONTENT ||
336:       this.community.phase === FeedPhase.CONTENT_WITH_INLINE_ERROR) {
337:       this.community.inlineError = false;
338:       this.community.recordPhase(FeedPhase.EMPTY);
339:     }
340:     if (this.forYou.modules.length > 0) {
341:       if (this.forYou.phase === FeedPhase.IDLE || this.forYou.phase === FeedPhase.EMPTY) {
342:         this.forYou.recordPhase(this.forYou.inlineError ? FeedPhase.CONTENT_WITH_INLINE_ERROR : FeedPhase.CONTENT);
343:       }
344:       return;
345:     }
346:     if (this.forYou.phase === FeedPhase.CONTENT || this.forYou.phase === FeedPhase.CONTENT_WITH_INLINE_ERROR) {
347:       this.forYou.inlineError = false;
348:       this.forYou.recordPhase(FeedPhase.EMPTY);
349:       return;
350:     }
351:     if (this.forYou.phase === FeedPhase.IDLE && this.allForYouModulesHidden()) {
352:       this.forYou.recordPhase(FeedPhase.EMPTY);
353:     }
354:   }
355: 
356:   private communityLanguage(community: Record<string, Object> | undefined): string {
357:     const language: string = this.snapshotText(community, ['language'], '');
358:     return language.length > 0 ? language : this.homeLanguage;
359:   }
360: 
361:   private forYouLanguage(forYouRecord: Record<string, Object> | undefined): string {
362:     const language: string = this.snapshotText(forYouRecord, ['language'], '');
363:     return language.length > 0 ? language : this.homeLanguage;
364:   }
365: 
366:   private hydratedForYouModules(forYouRecord: Record<string, Object> | undefined): FeedModule[] {
367:     const direct: Object | undefined = this.nested(forYouRecord, ['modules']);
368:     if (direct !== undefined) {
369:       return parseModules(direct, this.forYou.language);
370:     }
371:     const loose: Object | undefined = this.snapshot.value(['forYouModules']);
372:     if (loose !== undefined) {
373:       return parseModules(loose, this.forYou.language);
374:     }
375:     const backing: Object | undefined = this.snapshot.value(['forYouBackingModules']);
376:     if (backing !== undefined) {
377:       return parseModules(backing, this.forYou.language);
378:     }
379:     const state: Record<string, Object> | undefined = this.snapshot.record(['forYouState']);
380:     if (state !== undefined) {
381:       const modules: Object | undefined = this.nested(state, ['modules']);
382:       if (modules !== undefined) {
383:         return parseModules(modules, this.forYou.language);
384:       }
385:     }
386:     return [];
387:   }
388: 
389:   private restoreCacheFromSnapshot(): void {
390:     const entries: Record<string, Object> | undefined =
391:       this.snapshot.record(['persistedForYouCache', 'forYouCache']);
392:     if (entries === undefined) {
393:       return;
394:     }
395:     const date: string = normalizeDate(textField(entries, 'date'), this.clock.today());
396:     const languages: string[] = languagesOfCacheEntry(entries);
397:     for (let index = 0; index < languages.length; index++) {
398:       const modules: FeedModule[] = modulesFromCacheEntry(entries, languages[index]);
399:       if (modules.length > 0) {
400:         this.cache.set(date, languages[index], modules);
401:       }
402:     }
403:   }
404: 
405:   private snapshotText(record: Record<string, Object> | undefined, keys: string[], fallback: string): string {
406:     if (record === undefined) {
407:       return fallback;
408:     }
409:     for (let index = 0; index < keys.length; index++) {
410:       const value: Object | undefined = record[keys[index]];
411:       if (value !== undefined && value !== null) {
412:         return textField(record, keys[index]);
413:       }
414:     }
415:     return fallback;
416:   }
417: 
418:   private nested(record: Record<string, Object> | undefined, keys: string[]): Object | undefined {
419:     if (record === undefined) {
420:       return undefined;
421:     }
422:     for (let index = 0; index < keys.length; index++) {
423:       const value: Object | undefined = record[keys[index]];
424:       if (value !== undefined && value !== null) {
425:         return value;
426:       }
427:     }
428:     return undefined;
429:   }
430: 
431:   private nestedFlag(record: Record<string, Object> | undefined, keys: string[], fallback: boolean): boolean {
432:     if (record === undefined) {
433:       return fallback;
434:     }
435:     for (let index = 0; index < keys.length; index++) {
436:       const value: Object | undefined = record[keys[index]];
437:       if (value !== undefined && value !== null) {
438:         return textField(record, keys[index]) === 'true';
439:       }
440:     }
441:     return fallback;
442:   }
