444:   /* ---------------------------------------------------------------- *
445:    * Durable state.
446:    * ---------------------------------------------------------------- */
447: 
448:   /**
449:    * Re-reads the durable feed state. Values that durable storage does not hold
450:    * yet are taken from the injected snapshot and written back, so the choice the
451:    * reader made is stored by the same flow that reads it back later.
452:    */
453:   private async reloadPersistence(): Promise<void> {
454:     if (await this.preferences.contains(FeedStorageKeys.HOME_PREFERENCE)) {
455:       this.homePreference = homePreferenceOf(await this.preferences.readText(FeedStorageKeys.HOME_PREFERENCE));
456:     } else {
457:       this.homePreference = homePreferenceOf(this.snapshot.text(['homePreference', 'preference']));
458:       await this.preferences.writeText(FeedStorageKeys.HOME_PREFERENCE, `${this.homePreference}`);
459:     }
460:     if (await this.preferences.contains(FeedStorageKeys.HOME_LANGUAGE)) {
461:       this.homeLanguage = await this.preferences.readText(FeedStorageKeys.HOME_LANGUAGE);
462:     } else {
463:       this.homeLanguage = this.snapshot.text(['homeLanguage', 'persistedHomeLanguage', 'feedLanguage', 'language']);
464:       if (this.homeLanguage.length > 0) {
465:         await this.preferences.writeText(FeedStorageKeys.HOME_LANGUAGE, this.homeLanguage);
466:       }
467:     }
468:     if (await this.preferences.contains(FeedStorageKeys.HIDDEN_CARDS)) {
469:       this.hiddenCards = await this.preferences.readList(FeedStorageKeys.HIDDEN_CARDS);
470:     } else {
471:       this.hiddenCards = this.snapshot.list(['hiddenCards', 'persistedHiddenCards']);
472:       await this.preferences.writeList(FeedStorageKeys.HIDDEN_CARDS, this.hiddenCards);
473:     }
474:     if (await this.preferences.contains(FeedStorageKeys.HIDDEN_COMMUNITY_MODULES)) {
475:       this.hiddenCommunityModules = await this.preferences.readList(FeedStorageKeys.HIDDEN_COMMUNITY_MODULES);
476:     } else {
477:       this.hiddenCommunityModules = this.snapshot.list(
478:         ['hiddenCommunityModules', 'persistedCommunityHiddenModules', 'communityHiddenModules']);
479:       await this.preferences.writeList(FeedStorageKeys.HIDDEN_COMMUNITY_MODULES, this.hiddenCommunityModules);
480:     }
481:     if (await this.preferences.contains(FeedStorageKeys.HIDDEN_FOR_YOU_MODULES)) {
482:       this.hiddenForYouModules = await this.preferences.readList(FeedStorageKeys.HIDDEN_FOR_YOU_MODULES);
483:     } else {
484:       this.hiddenForYouModules = this.snapshot.list(
485:         ['hiddenModules', 'persistedHiddenModules', 'hiddenForYouModules', 'forYouHiddenModules']);
486:       await this.preferences.writeList(FeedStorageKeys.HIDDEN_FOR_YOU_MODULES, this.hiddenForYouModules);
487:     }
488:     if (await this.preferences.contains(FeedStorageKeys.ONBOARDING_COMPLETE)) {
489:       this.onboardingComplete = (await this.preferences.readText(FeedStorageKeys.ONBOARDING_COMPLETE)) === 'true';
490:     } else {
491:       await this.preferences.writeText(FeedStorageKeys.ONBOARDING_COMPLETE, `${this.onboardingComplete}`);
492:     }
493:     this.interestsList = await this.interestRepository.all();
494:   }
