496:   /* ---------------------------------------------------------------- *
497:    * Language.
498:    * ---------------------------------------------------------------- */
499: 
500:   /** The feed language actually used: the stored one when it is still configured. */
501:   activeLanguage(): string {
502:     return this.resolveLanguage(this.homeLanguage);
503:   }
504: 
505:   private resolveLanguage(stored: string): string {
506:     if (this.configuredLanguages.length === 0) {
507:       return stored.length > 0 ? stored : 'en';
508:     }
509:     if (stored.length > 0 && this.configuredLanguages.indexOf(stored) >= 0) {
510:       return stored;
511:     }
512:     if (this.primaryConfiguredLanguage.length > 0 &&
513:       this.configuredLanguages.indexOf(this.primaryConfiguredLanguage) >= 0) {
514:       return this.primaryConfiguredLanguage;
515:     }
516:     return this.configuredLanguages[0];
517:   }
518: 
519:   /** Selects a feed language from the configured app languages and reloads the active tab. */
520:   async setFeedLanguage(language: string): Promise<void> {
521:     if (this.configuredLanguages.length > 0 && this.configuredLanguages.indexOf(language) < 0) {
522:       return;
523:     }
524:     if (this.homeLanguage === language) {
525:       return;
526:     }
527:     this.homeLanguage = language;
528:     await this.preferences.writeText(FeedStorageKeys.HOME_LANGUAGE, language);
529:     await this.emit({
530:       name: 'homeLanguageChanged',
531:       leaf: 'analytics',
532:       surfaces: [FeedTabSurface.HOME],
533:       language: language,
534:       result: language
535:     });
536:     await this.reloadActiveTab(FeedLoadSource.LANGUAGE_CHANGED, true);
537:   }
538: 
539:   /* ---------------------------------------------------------------- *
540:    * Home surface lifecycle.
541:    * ---------------------------------------------------------------- */
542: 
543:   /** Rebuilds the surface from durable state and loads the tab the choice selects. */
544:   async recreateHomeSurface(): Promise<void> {
545:     await this.reloadPersistence();
546:     this.undo = undefined;
547:     const language: string = this.activeLanguage();
548:     this.homeLanguage = language;
549:     await this.preferences.writeText(FeedStorageKeys.HOME_LANGUAGE, language);
550:     const tab: HomeTab = homeTabForPreference(this.homePreference);
551:     this.community.reset(language, this.clock.today());
552:     this.forYou.reset(language, this.clock.today());
553:     this.selectedTab = tab;
554:     await this.emit({
555:       name: 'homeSurfaceRecreated',
556:       leaf: 'analytics',
557:       surfaces: [FeedTabSurface.HOME],
558:       language: language,
559:       result: `${tab}`
560:     });
561:     await this.onLoadMore(tab, FeedLoadSource.INITIAL);
562:   }
563: 
564:   /**
565:    * Returns to the foreground. An unavailable stored language falls back to a
566:    * configured one, which resets and reloads the active tab only; the peer tab
567:    * keeps whatever it was showing until it is selected again.
568:    */
569:   async resumeHomeSurface(): Promise<void> {
570:     await this.reloadPersistence();
571:     const resolved: string = this.activeLanguage();
572:     const changed: boolean = resolved !== this.homeLanguage;
573:     this.homeLanguage = resolved;
574:     if (changed) {
575:       await this.preferences.writeText(FeedStorageKeys.HOME_LANGUAGE, resolved);
576:       await this.emit({
577:         name: 'homeLanguageResolved',
578:         leaf: 'analytics',
579:         surfaces: [FeedTabSurface.HOME],
580:         language: resolved,
581:         result: resolved
582:       });
583:       await this.reloadActiveTab(FeedLoadSource.LANGUAGE_CHANGED, true);
584:       return;
585:     }
586:     await this.reloadActiveTab(FeedLoadSource.RESUME, false);
587:   }
588: 
589:   /** Resets the active tab and loads it again. */
590:   async refreshActiveTab(): Promise<void> {
591:     await this.reloadActiveTab(FeedLoadSource.REFRESH, true);
592:   }
593: 
594:   private async reloadActiveTab(source: FeedLoadSource, force: boolean): Promise<void> {
595:     if (this.tabInFlight(this.selectedTab)) {
596:       return;
597:     }
598:     if (!force && !this.activeTabIsStale()) {
599:       return;
600:     }
601:     this.resetTab(this.selectedTab, this.activeLanguage());
602:     await this.onLoadMore(this.selectedTab, source);
603:   }
604: 
605:   /** True when the active tab is showing a result from a previous calendar day. */
606:   private activeTabIsStale(): boolean {
607:     if (this.selectedTab === HomeTab.COMMUNITY) {
608:       if (this.community.phase === FeedPhase.IDLE) {
609:         return true;
610:       }
611:       return this.community.date.length > 0 && this.community.date !== this.clock.today();
612:     }
613:     if (this.forYou.phase === FeedPhase.IDLE) {
614:       return true;
615:     }
616:     return this.forYou.date.length > 0 && this.forYou.date !== this.clock.today();
617:   }
618: 
619:   /** Switches tab. Only an idle, non loading destination is loaded. */
620:   async selectHomeTab(tab: string): Promise<void> {
621:     const target: HomeTab | undefined = homeTabOf(tab);
622:     if (target === undefined) {
623:       return;
624:     }
625:     this.selectedTab = target;
626:     await this.emit({
627:       name: 'homeTabSelected',
628:       leaf: 'analytics',
629:       surfaces: [surfaceOf(target)],
630:       language: this.homeLanguage,
631:       result: `${target}`
632:     });
633:     if (this.tabInFlight(target)) {
634:       return;
635:     }
636:     if (this.isIdle(target)) {
637:       await this.onLoadMore(target, FeedLoadSource.INITIAL);
638:     }
639:   }
