641:   /* ---------------------------------------------------------------- *
642:    * Loading.
643:    * ---------------------------------------------------------------- */
644: 
645:   /** Retries the failed Community request for the same logical day. */
646:   async retryCommunityLoad(): Promise<void> {
647:     await this.onLoadMore(HomeTab.COMMUNITY, FeedLoadSource.RETRY);
648:   }
649: 
650:   /** Retries the failed Community load-more for the same logical day. */
651:   async retryCommunityLoadMore(): Promise<void> {
652:     await this.onLoadMore(HomeTab.COMMUNITY, FeedLoadSource.RETRY_MORE);
653:   }
654: 
655:   /** Retries the failed For You batch through the same load-more entry point. */
656:   async retryForYouLoad(): Promise<void> {
657:     await this.onLoadMore(HomeTab.FOR_YOU, FeedLoadSource.RETRY);
658:   }
659: 
660:   /** Requests the next logical Community day. */
661:   async loadCommunityMore(): Promise<void> {
662:     await this.onLoadMore(HomeTab.COMMUNITY, FeedLoadSource.LOAD_MORE);
663:   }
664: 
665:   /** Serves the stable daily For You result. */
666:   async loadForYouMore(): Promise<void> {
667:     await this.onLoadMore(HomeTab.FOR_YOU, FeedLoadSource.LOAD_MORE);
668:   }
669: 
670:   /**
671:    * The single entry point every feed request goes through, including the retry
672:    * actions bound to the error presentations.
673:    */
674:   private async onLoadMore(tab: HomeTab, source: FeedLoadSource): Promise<void> {
675:     if (this.disposed) {
676:       return;
677:     }
678:     if (tab === HomeTab.COMMUNITY) {
679:       await this.loadCommunity(source);
680:       return;
681:     }
682:     await this.loadForYou(source);
683:   }
684: 
685:   private tabInFlight(tab: HomeTab): boolean {
686:     return tab === HomeTab.COMMUNITY ? this.communityInFlight : this.forYouInFlight;
687:   }
688: 
689:   private isIdle(tab: HomeTab): boolean {
690:     return tab === HomeTab.COMMUNITY ? this.community.phase === FeedPhase.IDLE : this.forYou.phase === FeedPhase.IDLE;
691:   }
692: 
693:   private resetTab(tab: HomeTab, language: string): void {
694:     if (tab === HomeTab.COMMUNITY) {
695:       this.community.reset(language, this.clock.today());
696:       return;
697:     }
698:     this.forYou.reset(language, this.clock.today());
699:   }
700: 
701:   private async loadCommunity(source: FeedLoadSource): Promise<void> {
702:     if (this.communityInFlight) {
703:       return;
704:     }
705:     if (this.communityLoadingIsSuppressed()) {
706:       return;
707:     }
708:     this.communityInFlight = true;
709:     const logicalAge: number = this.community.nextLogicalAge;
710:     const language: string = this.community.language.length > 0 ? this.community.language : this.activeLanguage();
711:     const request: CommunityRequest = new CommunityRequest(
712:       language,
713:       this.clock.today(),
714:       logicalAge,
715:       this.content.attemptsFor(`community:${logicalAge}`) + 1,
716:       this.content.attemptsFor(`community:${logicalAge}`) + 1,
717:       source);
718:     this.community.beginLoading(source);
719:     try {
720:       const page: CommunityPage = await this.content.fetchCommunity(request);
721:       this.applyCommunityPage(page);
722:     } catch (error) {
723:       this.applyCommunityFailure(errorText(error), logicalAge);
724:     } finally {
725:       this.communityInFlight = false;
726:       this.community.endLoading();
727:     }
728:   }
729: 
730:   private communityLoadingIsSuppressed(): boolean {
731:     if (this.allCommunityModulesHidden()) {
732:       this.community.retryAvailable = false;
733:       this.community.inlineError = false;
734:       this.community.recordPhase(FeedPhase.EMPTY);
735:       this.evaluateCommunityEmptyState();
736:       return true;
737:     }
738:     return false;
739:   }
740: 
741:   private applyCommunityPage(page: CommunityPage): void {
742:     const incoming: FeedCard[] = page.cards;
743:     const merged: FeedCard[] = mergeCommunityCards(this.community.backingCards, incoming, page.logicalAge,
744:       this.community.language);
745:     this.community.backingCards = merged;
746:     this.community.date = page.date;
747:     // A served page is what advances pagination; a failure never does.
748:     this.community.nextLogicalAge = page.logicalAge + 1;
749:     this.community.failedLogicalAge = -1;
750:     this.community.inlineError = false;
751:     this.community.retryAvailable = false;
752:     this.refreshCommunityPresentation();
753:     this.evaluateCommunityEmptyState();
754:     this.community.recordPhase(this.community.cards.length > 0 ? FeedPhase.CONTENT : FeedPhase.EMPTY);
755:   }
756: 
757:   private applyCommunityFailure(kind: string, logicalAge: number): void {
758:     this.community.failedLogicalAge = logicalAge;
759:     this.community.retryAvailable = true;
760:     this.community.recoveryAction = FeedRecoveryAction.RETRY;
761:     this.community.secondaryRecoveryAction = FeedRecoveryAction.NONE;
762:     if (this.community.cards.length > 0) {
763:       // Content that is already on screen survives a later page failure.
764:       this.community.inlineError = true;
765:       this.community.recordPhase(FeedPhase.CONTENT_WITH_INLINE_ERROR);
766:       return;
767:     }
768:     this.community.inlineError = false;
769:     this.community.recordPhase(FeedPhase.ERROR);
770:   }
