772:   private async loadForYou(source: FeedLoadSource): Promise<void> {
773:     if (this.forYouInFlight) {
774:       return;
775:     }
776:     if (this.forYouLoadingIsSuppressed()) {
777:       return;
778:     }
779:     const language: string = this.forYou.language.length > 0 ? this.forYou.language : this.activeLanguage();
780:     const date: string = this.clock.today();
781:     if (source === FeedLoadSource.LOAD_MORE && this.forYou.hasContent() && this.cache.isUsable(this.forYou.date, language)) {
782:       // The daily result for this language is stable; paging inside a day adds nothing.
783:       this.forYou.stableResult = true;
784:       return;
785:     }
786:     this.forYouInFlight = true;
787:     try {
788:       if (this.cache.isUsable(date, language)) {
789:         await this.restoreForYouFromCache(date, language, source);
790:         return;
791:       }
792:       const batch: number = this.forYou.batchIndex;
793:       const request: ForYouRequest = new ForYouRequest(
794:         language, date, batch, this.content.attemptsFor(`for_you:${batch}`) + 1, source);
795:       this.forYou.beginLoading(source);
796:       try {
797:         const page: ForYouPage = await this.content.fetchForYou(request);
798:         await this.applyForYouPage(page, batch);
799:       } catch (error) {
800:         this.applyForYouFailure(errorText(error), batch);
801:       } finally {
802:         this.forYou.endLoading();
803:       }
804:     } finally {
805:       this.forYouInFlight = false;
806:     }
807:   }
