809:   private forYouLoadingIsSuppressed(): boolean {
810:     if (this.allForYouModulesHidden()) {
811:       this.forYou.retryAvailable = false;
812:       this.forYou.inlineError = false;
813:       this.forYou.recordPhase(FeedPhase.EMPTY);
814:       this.evaluateForYouEmptyState();
815:       return true;
816:     }
817:     return false;
818:   }
