820:   private async restoreForYouFromCache(date: string, language: string, source: FeedLoadSource): Promise<void> {
821:     const modules: FeedModule[] = this.cache.get(language) as FeedModule[];
822:     this.forYou.beginLoading(source);
823:     this.forYou.backingModules = modules;
824:     this.forYou.language = language;
825:     this.forYou.date = date;
826:     this.forYou.failedBatch = -1;
827:     this.forYou.inlineError = false;
828:     this.forYou.retryAvailable = false;
829:     this.forYou.stableResult = true;
830:     this.forYou.endLoading();
831:     this.refreshForYouPresentation();
832:     this.evaluateForYouEmptyState();
833:     this.forYou.recordPhase(this.forYou.modules.length > 0 ? FeedPhase.CONTENT : FeedPhase.EMPTY);
834:     await this.emit({
835:       name: 'forYouCacheRestored',
836:       leaf: 'analytics',
837:       surfaces: [FeedTabSurface.FOR_YOU],
838:       language: language,
839:       date: date,
840:       batch: this.forYou.batchIndex,
841:       result: 'CACHE_HIT'
842:     });
843:   }
