845:   private async applyForYouPage(page: ForYouPage, batch: number): Promise<void> {
846:     this.forYou.backingModules = this.deriveForYouModules(page.language, page.date, page.rankedTitles);
847:     this.forYou.language = page.language;
848:     this.forYou.date = page.date;
849:     // The batch index only advances once a batch has been served.
850:     this.forYou.batchIndex = batch + 1;
851:     this.forYou.failedBatch = -1;
852:     this.forYou.inlineError = false;
853:     this.forYou.retryAvailable = false;
854:     this.forYou.stableResult = false;
855:     this.cache.set(page.date, page.language, this.forYou.backingModules);
856:     await this.persistCache();
857:     this.refreshForYouPresentation();
858:     this.evaluateForYouEmptyState();
859:     this.forYou.recordPhase(this.forYou.modules.length > 0 ? FeedPhase.CONTENT : FeedPhase.EMPTY);
860:   }
861: 
862:   private applyForYouFailure(kind: string, batch: number): void {
863:     this.forYou.failedBatch = batch;
864:     this.forYou.retryAvailable = true;
865:     this.forYou.recoveryAction = FeedRecoveryAction.RETRY;
866:     this.forYou.secondaryRecoveryAction = FeedRecoveryAction.NONE;
867:     if (this.forYou.modules.length > 0) {
868:       this.forYou.inlineError = true;
869:       this.forYou.recordPhase(FeedPhase.CONTENT_WITH_INLINE_ERROR);
870:       return;
871:     }
872:     this.forYou.inlineError = false;
873:     this.forYou.recordPhase(FeedPhase.ERROR);
874:   }
