876:   /**
877:    * Derives the For You recommendation groups from the reader's saved interests,
878:    * reading activity and saved articles. Titles ranked by the recommendation
879:    * leaf are folded into the group they belong to; the ranking itself is not.
880:    */
881:   private deriveForYouModules(language: string, date: string, rankedTitles: string[]): FeedModule[] {
882:     const modules: FeedModule[] = [];
883:     const interests: string[] = titlesForLanguage(this.interestsList, language);
884:     const reading: string[] = titlesForLanguage(this.readingActivity, language);
885:     const saved: string[] = titlesForLanguage(this.savedArticles, language);
886:     appendModule(modules, 'BASED_ON_INTEREST', interests, rankedTitles);
887:     appendModule(modules, 'BECAUSE_YOU_READ', reading, rankedTitles);
888:     appendModule(modules, 'CONTINUE_READING', saved, rankedTitles);
889:     return modules;
890:   }
