896:   private refreshCommunityPresentation(): void {
897:     const visible: FeedCard[] = [];
898:     const hiddenModules: string[] = this.hiddenCommunityModules;
899:     for (let index = 0; index < this.community.backingCards.length; index++) {
900:       const card: FeedCard = this.community.backingCards[index];
901:       if (this.hiddenCards.indexOf(card.hideKey()) >= 0) {
902:         continue;
903:       }
904:       if (!isDayHeader(card.type) && hiddenModules.indexOf(moduleTypeOf(card)) >= 0) {
905:         continue;
906:       }
907:       visible.push(card);
908:     }
909:     this.community.cards = visible;
910:   }
911: 
912:   private refreshForYouPresentation(): void {
913:     const presented: FeedModule[] = [];
914:     const hiddenModules: string[] = this.hiddenForYouModules;
915:     for (let index = 0; index < this.forYou.backingModules.length; index++) {
916:       const module: FeedModule = this.forYou.backingModules[index];
917:       if (hiddenModules.indexOf(module.type) >= 0) {
918:         continue;
919:       }
920:       const cards: FeedCard[] = module.visibleCards(this.hiddenCards);
921:       if (cards.length === 0) {
922:         continue;
923:       }
924:       presented.push(new FeedModule(module.type, cards));
925:     }
926:     this.forYou.modules = presented;
927:   }
