929:   private evaluateCommunityEmptyState(): void {
930:     if (this.community.cards.length > 0) {
931:       this.community.emptyReason = FeedEmptyReason.NONE;
932:       this.community.recoveryAction = FeedRecoveryAction.NONE;
933:       this.community.secondaryRecoveryAction = FeedRecoveryAction.NONE;
934:       return;
935:     }
936:     if (this.allCommunityModulesHidden()) {
937:       this.community.emptyReason = FeedEmptyReason.ALL_MODULES_HIDDEN;
938:       this.community.recoveryAction = FeedRecoveryAction.OPEN_COMMUNITY_MODULES;
939:       this.community.secondaryRecoveryAction = FeedRecoveryAction.NONE;
940:       return;
941:     }
942:     this.community.emptyReason = FeedEmptyReason.NO_DATA;
943:     this.community.recoveryAction = FeedRecoveryAction.RETRY;
944:     this.community.secondaryRecoveryAction = FeedRecoveryAction.OPEN_COMMUNITY_MODULES;
945:   }
946: 
947:   private evaluateForYouEmptyState(): void {
948:     if (this.forYou.modules.length > 0) {
949:       this.forYou.emptyReason = FeedEmptyReason.NONE;
950:       this.forYou.recoveryAction = FeedRecoveryAction.NONE;
951:       this.forYou.secondaryRecoveryAction = FeedRecoveryAction.NONE;
952:       return;
953:     }
954:     if (this.allForYouModulesHidden()) {
955:       this.forYou.emptyReason = FeedEmptyReason.ALL_MODULES_HIDDEN;
956:       this.forYou.recoveryAction = FeedRecoveryAction.OPEN_FOR_YOU_MODULES;
957:       this.forYou.secondaryRecoveryAction = FeedRecoveryAction.NONE;
958:       return;
959:     }
960:     this.forYou.emptyReason = FeedEmptyReason.NO_DATA;
961:     this.forYou.recoveryAction = FeedRecoveryAction.CUSTOMIZE_INTERESTS;
962:     this.forYou.secondaryRecoveryAction = FeedRecoveryAction.RETURN_TO_COMMUNITY;
