1010:     // Hiding a module filters the backing recommendation groups; the daily cache
1011:     // keeps them so restoring visibility does not need another request.
1012:     this.hiddenForYouModules = allForYouModuleTypes();
1013:     await this.persistModuleVisibility();
1014:     this.refreshForYouPresentation();
