1048:   /** Hides one card. The removal shows immediately and the undo that follows restores it. */
1049:   async hideCard(token: string): Promise<void> {
1050:     const communityIndex: number = indexOfCard(this.community.backingCards, token);
1051:     if (communityIndex >= 0) {
1052:       const card: FeedCard = this.community.backingCards[communityIndex];
1053:       this.undo = new HideUndo('card', card.token(), card.hideKey(), `${HomeTab.COMMUNITY}`,
1054:         cardTokens(this.community.backingCards), moduleCardTokens(this.forYou.backingModules));
1055:       this.addHiddenCard(card.hideKey());
1056:       this.community.backingCards.splice(communityIndex, 1);
1057:       this.refreshCommunityPresentation();
1058:       this.evaluateCommunityEmptyState();
1059:       await this.persistHiddenCards();
1060:       await this.emit({
1061:         name: 'cardHidden',
1062:         leaf: 'analytics',
1063:         surfaces: [FeedTabSurface.COMMUNITY],
1064:         result: card.token()
1065:       });
1066:       return;
1067:     }
1068:     const module: FeedModule | undefined = findModuleWithCard(this.forYou.backingModules, token);
1069:     if (module === undefined) {
1070:       return;
1071:     }
1072:     const cardIndex: number = indexOfCard(module.cards, token);
1073:     const card: FeedCard = module.cards[cardIndex];
1074:     this.undo = new HideUndo('card', card.token(), card.hideKey(), `${HomeTab.FOR_YOU}`,
1075:       cardTokens(this.community.backingCards), moduleCardTokens(this.forYou.backingModules));
1076:     this.addHiddenCard(card.hideKey());
1077:     module.cards.splice(cardIndex, 1);
1078:     this.refreshForYouPresentation();
1079:     this.evaluateForYouEmptyState();
1080:     await this.persistHiddenCards();
1081:     await this.emit({
1082:       name: 'cardHidden',
1083:       leaf: 'analytics',
1084:       surfaces: [FeedTabSurface.FOR_YOU],
1085:       result: card.token()
1086:     });
1087:   }
