1089:   /** Hides one module of the active tab. */
1090:   async hideModule(moduleType: string): Promise<void> {
1091:     const onCommunity: boolean = this.communityCardsUseModule(moduleType);
1092:     this.undo = new HideUndo('module', moduleType, moduleType,
1093:       onCommunity ? `${HomeTab.COMMUNITY}` : `${HomeTab.FOR_YOU}`,
1094:       cardTokens(this.community.backingCards), moduleCardTokens(this.forYou.backingModules));
1095:     if (onCommunity) {
1096:       this.addHidden(this.hiddenCommunityModules, moduleType);
1097:     } else {
1098:       this.addHidden(this.hiddenForYouModules, moduleType);
