1100:     await this.persistModuleVisibility();
1101:     this.refreshCommunityPresentation();
1102:     this.refreshForYouPresentation();
1103:     this.evaluateCommunityEmptyState();
1104:     this.evaluateForYouEmptyState();
1105:     await this.emit({
1106:       name: 'moduleHidden',
1107:       leaf: 'analytics',
1108:       surfaces: [onCommunity ? FeedTabSurface.COMMUNITY : FeedTabSurface.FOR_YOU],
1109:       result: moduleType
1110:     });
1111:   }
