1113:   /** Restores whatever the last hide action removed, at the position it had. */
1114:   async undoLastHide(): Promise<void> {
1115:     const undo: HideUndo | undefined = this.undo;
1116:     if (undo === undefined) {
1117:       return;
1118:     }
1119:     this.undo = undefined;
1120:     if (undo.kind === 'module') {
1121:       this.removeHidden(undo.tab === `${HomeTab.COMMUNITY}` ?
1122:         this.hiddenCommunityModules : this.hiddenForYouModules, undo.token);
1123:     } else {
1124:       this.removeHiddenCard(undo.hideKey);
1125:     }
1126:     if (undo.tab === `${HomeTab.COMMUNITY}`) {
1127:       this.community.backingCards = parseCardsWithHeaders(undo.communityCards, this.community.language);
1128:     } else {
1129:       this.forYou.backingModules = parseModules(undo.forYouCards, this.forYou.language);
1130:     }
1131:     await this.persistHiddenCards();
1132:     await this.persistModuleVisibility();
1133:     this.refreshCommunityPresentation();
1134:     this.refreshForYouPresentation();
1135:     this.evaluateCommunityEmptyState();
1136:     this.evaluateForYouEmptyState();
1137:     await this.emit({
1138:       name: 'hideUndone',
1139:       leaf: 'analytics',
1140:       surfaces: [undo.tab === `${HomeTab.COMMUNITY}` ? FeedTabSurface.COMMUNITY : FeedTabSurface.FOR_YOU],
1141:       result: undo.token
1142:     });
1143:   }
