1201:   /**
1202:    * Completes the interest editor. An actual change is written to the interest
1203:    * repository first, then answers RESULT_INTERESTS_UPDATED, which invalidates
1204:    * the personalized content and refreshes For You. An unchanged editor answers
1205:    * RESULT_OK and touches neither the cache nor either tab.
1206:    */
1207:   async finishInterestEditing(): Promise<void> {
1208:     const changed: boolean = this.editor.wouldUpdate();
1209:     if (changed) {
1210:       const selections: string[] = this.editor.currentSelections.length > 0 ?
1211:         this.editor.currentSelections : this.interestsList;
1212:       await this.interestRepository.replaceAll(selections);
1213:       this.interestsList = await this.interestRepository.all();
1214:       this.lastActivityResult = this.editor.pendingResult > 0 ?
1215:         this.editor.pendingResult : FeedActivityResult.RESULT_INTERESTS_UPDATED;
1216:       await this.preferences.writeList(FeedStorageKeys.FOR_YOU_CACHE, []);
1217:       this.cache.clear();
1218:       await this.persistCache();
1219:       await this.emit({
1220:         name: 'interestsPersisted',
1221:         leaf: 'analytics',
1222:         surfaces: [FeedTabSurface.INTEREST_EDITOR],
1223:         result: `${this.interestRepository.storageName()}`
1224:       });
1225:       await this.emit({
1226:         name: 'personalizedContentInvalidated',
1227:         leaf: 'analytics',
1228:         surfaces: [FeedTabSurface.FOR_YOU],
1229:         date: this.clock.today(),
1230:         result: 'INVALIDATED'
1231:       });
1232:       this.editor.result = this.lastActivityResult;
1233:       await this.emit({
1234:         name: 'interestEditorFinished',
1235:         leaf: 'analytics',
1236:         surfaces: [FeedTabSurface.INTEREST_EDITOR],
1237:         value: this.lastActivityResult,
1238:         result: 'RESULT_INTERESTS_UPDATED'
1239:       });
1240:       await this.refreshForYouAfterInterestChange();
1241:       return;
1242:     }
1243:     this.lastActivityResult = this.editor.pendingResult >= 0 && this.editor.pendingResult !== 100 ?
1244:       this.editor.pendingResult : FeedActivityResult.RESULT_OK;
1245:     this.editor.result = this.lastActivityResult;
1246:     await this.emit({
1247:       name: 'interestEditorFinished',
